package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct {
	OrId    string // PIC X(5) @0 len=5
	OrStat  string // PIC X(1) @5 len=1
	OrQty   int64  // PIC 9(3) @6 len=3
	OrPrice decimal.Decimal
}

var WsEofFlag string = "N"
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsGrand decimal.Decimal = decimal.NewFromInt(0)
var WsNewCount int64 = 0
var WsShipCount int64 = 0
var WsCancelCount int64 = 0
var WsInvalid int64 = 0
var WsBadQty int64 = 0
var WsQtyEd string
var WsPriceEd string
var WsTotalEd string
var WsGrandEd string

var OrderRecVar OrderRec

var orderLines []string
var orderIdx int

func isInputDone() bool { return WsEofFlag == "Y" }

func pow10(n int) int64 {
	r := int64(1)
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func parseDigits(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	// keep only digits, handle all spaces already
	// if contains non-digits, treat as 0 for safety
	var v int64 = 0
	for _, c := range t {
		if c < '0' || c > '9' {
			return 0
		}
		v = v*10 + int64(c-'0')
	}
	return v
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func formatCount2(v int64) string {
	v = v % 100
	if v < 0 {
		v += 100
	}
	return fmt.Sprintf("%02d", v)
}

func formatEdited(val decimal.Decimal, picture string) string {
	// split picture at '.'
	dotIdx := strings.Index(picture, ".")
	var intPat, fracPat string
	if dotIdx >= 0 {
		intPat = picture[:dotIdx]
		fracPat = picture[dotIdx+1:]
	} else {
		intPat = picture
		fracPat = ""
	}
	numIntSlots := 0
	for _, c := range intPat {
		if c == 'Z' || c == '9' {
			numIntSlots++
		}
	}
	scale := 0
	for _, c := range fracPat {
		if c == 'Z' || c == '9' {
			scale++
		}
	}
	neg := val.IsNegative()
	av := val.Abs()
	// scaled integer (truncate toward zero, value already at scale)
	shifted := av.Shift(int32(scale)).Truncate(0)
	scaledInt := shifted.IntPart() // fits in int64 for our ranges
	var intPart, fracPart int64
	if scale > 0 {
		p := pow10(scale)
		intPart = scaledInt / p
		fracPart = scaledInt % p
		if fracPart < 0 {
			fracPart = -fracPart
		}
	} else {
		intPart = scaledInt
		fracPart = 0
	}
	if numIntSlots > 0 {
		m := pow10(numIntSlots)
		intPart = intPart % m
	}
	intDigits := make([]byte, numIntSlots)
	tmp := intPart
	for i := numIntSlots - 1; i >= 0; i-- {
		intDigits[i] = byte('0' + tmp%10)
		tmp /= 10
	}
	fracDigits := make([]byte, scale)
	tmp2 := fracPart
	for i := scale - 1; i >= 0; i-- {
		fracDigits[i] = byte('0' + tmp2%10)
		tmp2 /= 10
	}
	var b strings.Builder
	intIdx := 0
	fracIdx := 0
	seen := false
	// For sign handling (not needed, values non-negative) ignore.
	_ = neg
	for _, c := range intPat {
		switch c {
		case 'Z', '9':
			d := intDigits[intIdx]
			intIdx++
			if d != '0' {
				seen = true
				b.WriteByte(d)
			} else {
				if seen {
					b.WriteByte('0')
				} else {
					// check if any later int digit is non-zero?
					// If so, this zero is leading -> blank for Z, '0' for 9?
					// Actually for 9, always print digit; for Z blank until non-zero seen.
					// But seen==false means all previous are zero; need lookahead:
					// if all remaining (including current) are zero, Z blanks, 9 prints 0.
					// If some later is non-zero, current leading zero: Z blanks, 9 prints 0.
					// So same: Z->space, 9->'0'.
					if c == '9' {
						b.WriteByte('0')
					} else {
						b.WriteByte(' ')
					}
				}
			}
		case ',':
			if seen {
				b.WriteByte(',')
			} else {
				b.WriteByte(' ')
			}
		default:
			b.WriteByte(byte(c))
		}
	}
	if dotIdx >= 0 {
		b.WriteByte('.')
		for _, c := range fracPat {
			switch c {
			case 'Z', '9':
				d := byte('0')
				if fracIdx < len(fracDigits) {
					d = fracDigits[fracIdx]
				}
				fracIdx++
				// fractional 9 always prints; Z: same rule but after decimal typically print zero
				// Simplify: always print digit.
				_ = c
				b.WriteByte(d)
			default:
				b.WriteByte(byte(c))
			}
		}
	}
	return b.String()
}

func storePic99(v int64) int64 {
	v = v % 100
	if v < 0 {
		v += 100
	}
	return v
}

func store9_8V99(v decimal.Decimal) decimal.Decimal {
	// truncate toward zero to 2 decimals, then drop high-order digits
	v = v.Truncate(2)
	mod := decimal.NewFromInt(pow10(8)) // 10^8
	// values are non-negative in this program
	if v.IsNegative() {
		// keep low-order: v mod 10^8 preserving sign
		q := v.Div(mod).Truncate(0)
		v = v.Sub(q.Mul(mod))
	} else {
		q := v.Div(mod).Truncate(0)
		v = v.Sub(q.Mul(mod))
	}
	return v
}

func addToGrand(v decimal.Decimal) {
	WsGrand = WsGrand.Add(v).Truncate(2)
	mod := decimal.NewFromInt(pow10(10))
	if WsGrand.GreaterThanOrEqual(mod) || WsGrand.LessThan(decimal.NewFromInt(0).Sub(mod)) {
		q := WsGrand.Div(mod).Truncate(0)
		WsGrand = WsGrand.Sub(q.Mul(mod))
	}
	// ensure scale
	WsGrand = WsGrand.Truncate(2)
}

func MAINPARA() {
	f, err := os.Open("input.dat")
	if err != nil {
		// treat missing as empty
		orderLines = nil
	} else {
		sc := bufio.NewScanner(f)
		// allow long lines
		sc.Buffer(make([]byte, 1024*1024), 1024*1024)
		for sc.Scan() {
			line := sc.Text()
			// strip trailing \r if present (Scanner strips \n, keeps \r on CRLF? Actually strips \r\n? ScanLines strips \r)
			if strings.HasSuffix(line, "\r") {
				line = strings.TrimSuffix(line, "\r")
			}
			orderLines = append(orderLines, line)
		}
		f.Close()
	}
	orderIdx = 0
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	// CLOSE ORDER-FILE (nothing)
	SUMMARYPARA()
}

func READPARA() {
	if orderIdx >= len(orderLines) {
		WsEofFlag = "Y"
		return
	}
	line := orderLines[orderIdx]
	orderIdx++
	// pad/truncate to 15
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	OrderRecVar.OrId = line[0:5]
	OrderRecVar.OrStat = line[5:6]
	OrderRecVar.OrQty = parseDigits(line[6:9])
	n := parseDigits(line[9:15])
	OrderRecVar.OrPrice = decimal.New(n, -2)
}

func PROCESSPARA() {
	WsTotal = decimal.NewFromInt(0)
	if OrderRecVar.OrQty == 0 {
		WsBadQty = storePic99(WsBadQty + 1)
		fmt.Fprint(os.Stdout, OrderRecVar.OrId+" BAD QTY\n")
	} else if OrderRecVar.OrStat == "N" {
		qtyDec := decimal.NewFromInt(OrderRecVar.OrQty)
		v := qtyDec.Mul(OrderRecVar.OrPrice).Truncate(2)
		WsTotal = store9_8V99(v)
		WsNewCount = storePic99(WsNewCount + 1)
		SHOWPARA()
	} else if OrderRecVar.OrStat == "S" {
		qtyDec := decimal.NewFromInt(OrderRecVar.OrQty)
		v := qtyDec.Mul(OrderRecVar.OrPrice).Mul(decimal.NewFromFloat(1.05))
		v = v.Round(2)
		WsTotal = store9_8V99(v)
		WsShipCount = storePic99(WsShipCount + 1)
		SHOWPARA()
	} else if OrderRecVar.OrStat == "C" {
		WsCancelCount = storePic99(WsCancelCount + 1)
		SHOWPARA()
	} else {
		WsInvalid = storePic99(WsInvalid + 1)
		fmt.Fprint(os.Stdout, OrderRecVar.OrId+" BAD STATUS "+OrderRecVar.OrStat+"\n")
	}
	addToGrand(WsTotal)
	READPARA()
}

func SHOWPARA() {
	WsQtyEd = formatEdited(decimal.NewFromInt(OrderRecVar.OrQty), "ZZ9")
	WsPriceEd = formatEdited(OrderRecVar.OrPrice, "Z,ZZ9.99")
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZ9.99")
	fmt.Fprint(os.Stdout, OrderRecVar.OrId+" "+OrderRecVar.OrStat+" "+WsQtyEd+" "+WsPriceEd+" "+WsTotalEd+"\n")
}

func SUMMARYPARA() {
	WsGrandEd = formatEdited(WsGrand, "Z,ZZZ,ZZZ,ZZ9.99")
	fmt.Fprint(os.Stdout, "NEW: "+formatCount2(WsNewCount)+" SHIPPED: "+formatCount2(WsShipCount)+" CANCELLED: "+formatCount2(WsCancelCount)+"\n")
	fmt.Fprint(os.Stdout, "INVALID: "+formatCount2(WsInvalid)+" BAD QTY: "+formatCount2(WsBadQty)+"\n")
	fmt.Fprint(os.Stdout, "GRAND TOTAL: "+WsGrandEd+"\n")
}

func main() {
	MAINPARA()
}
